#include <iostream>
#include <string>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::string n;
    std::getline(std::cin, n);

    int a = 0;
    for (char c : n) {
        if (c == 'a') {
            a++;
        }
    }

    if (a > static_cast<int>(n.length()) / 2) {
        std::cout << n.length() << '\n';
    } else {
        std::cout << (a + (a - 1)) << '\n';
    }

    return 0;
}

